import{_ as s,l as n,o as e,c as l,v as o,p as i,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Lampson 保护","description":"","frontmatter":{"title":"Lampson 保护","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lampson-protection.md","filePath":"cs/lampson-protection.md","lastUpdated":1789023840000}'),m={name:"cs/lampson-protection.md"};function h(A,a,E,B,_,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="lampson-保护" tabindex="-1">Lampson 保护 <a class="header-anchor" href="#lampson-保护" aria-label="Permalink to &quot;Lampson 保护&quot;">​</a></h1><div class="epigraph"><p>保护是主体、客体与权利的矩阵；机制应能表达政策，而不把政策焊死在某一种操作系统里。</p><footer>—— Lampson, Protection, 1971；重刊 ACM Operating Systems Review, 1974</footer></div><p><a href="/cs/lamport-clocks">上一课</a>附录对照了无共享时钟时的因果。附录对照，不插入主干。主干已在<a href="/cs/acl-least-priv">访问控制与最小特权</a>、<a href="/cs/dac-mac-rbac">DAC/MAC/RBAC</a>、<a href="/cs/capability-vs-acl">能力对 ACL</a>里用过保护矩阵与两种存放；这里对照 <strong>Lampson 原文的问题</strong>：如何把「谁可以对什么做什么」写成可实现的抽象，并讨论域切换与放大。不重做 Unix mode。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lamport 处理事件序，不处理授权。Lampson 的缺口是保护：访问矩阵、域、把矩阵按列存成 ACL、按行发成能力，以及从用户态进入更特权域的受控门。主干安全课在数据库之后才命名 CIA，但矩阵观念来自这篇。附录只对照原文如何把保护从「操作系统功能列表」里抽成对象。</p><p><span class="marginnote">Saltzer 与 Schroeder 1975 把最小特权等原则写成更长的教程。Lampson 更短、更机制。不要给两篇发明编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>矩阵条目是权利。当前域决定能用哪一行。系统调用是换域。能力必须不可伪造（标签、加密、或硬件）。主干能力课已取用「持票即允许」；ACL 课取用按客体存名单。本附录不把 RBAC 写回 1971。</p>',8)),(e(),i(d,null,{default:t(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAT%5B%22%E4%B8%BB%E4%BD%93%20x%20%E5%AE%A2%E4%BD%93%E7%9A%84%E6%9D%83%E5%88%A9%22%5D%20--%3E%20ACL%5B%22%E6%8C%89%E5%88%97%3A%20ACL%22%5D%0A%20%20MAT%20--%3E%20CAP%5B%22%E6%8C%89%E8%A1%8C%3A%20%E8%83%BD%E5%8A%9B%22%5D%0A%20%20GATE%5B%22%E5%8F%97%E6%8E%A7%E6%8D%A2%E5%9F%9F%22%5D%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E7%89%B9%E6%9D%83%E7%BA%A7%E4%B8%8E%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一旦保护是矩阵，完整中介、失败安全、最小特权才有落点。THE 分层是结构；Lampson 补的是权利语言。后文 Cerf–Kahn 管互联，不管矩阵——所以安全课不能提前用 1974 网络文代替本篇。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干按系统栈：先比特与 OS 隔离硬件，安全课在库之后才开 CIA。把 1971 插在 THE 之后当必修「下一课」，会让读者以为保护是 OS 附录而不是安全主干。本篇只对照原文对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1971 与 Bell–LaPadula 混成一篇。也不要在附录里开信息流形式语义。下一篇对照 Cerf–Kahn 1974 分组互联。</p><p>对照结束应回到主干<a href="/cs/acl-least-priv">访问控制</a>与<a href="/cs/privilege-rings">特权级</a>。保护矩阵不插入网络课中间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Lampson 1971/1974：保护 = 矩阵 + 换域。</li><li>主干 ACL/能力课已取用；本篇不插入安全课之前当课序。</li><li>出处：Lampson, Protection, 1971/1974。</li></ul>',9))])}const T=s(m,[["render",h]]);export{C as __pageData,T as default};
